INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'LOGICAL', 'Four balls and four boxes are colored Yellow, Pink, Red, and Green. The Red ball is in a box whose color matches the ball in the Yellow box. The Red box contains the Green ball. In which box is the Yellow ball?', 'Yellow Box', 'Pink Box', 'Red Box', 'Green Box', 'D', 'Applying all the clues leaves the Green box as the only possible location.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'LOGICAL', 'Every day in his business, a merchant had to weigh amounts from 1 kg to 121 kg to the nearest kilogram. What is the minimum number of weights required, and what should their weights be?', '4 weights (1, 2, 4, 8)', '5 weights (1, 3, 9, 27, 81)', '6 weights (1, 2, 4, 8, 16, 32)', '7 weights (1, 3, 9, 27, 54, 81, 121)', 'B', 'Using balanced ternary, the minimum weights are 1, 3, 9, 27, and 81 kg.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'QUANTITATIVE', 'Y catches 5 times more fish than X. If the total number of fish caught by X and Y is 42, how many fish did X catch?', '5', '6', '7', '8', 'C', 'Let X=x, Y=5x. Then 6x=42, so X=7.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'QUANTITATIVE', 'Three companies independently receive savings of 20%, 30%, and 40%, respectively. If the companies are considered together, what is their net percentage saving?', '0.25', '0.3', '0.35', '0.4', 'B', 'Assume ₹100 each. Total savings = ₹90 out of ₹300, so net saving = 30%.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'QUANTITATIVE', 'The ratio of the incomes of C and D is 3:4, and the ratio of their expenditures is 4:5. If C''s savings are one-fourth of his income, find the ratio of their savings.', '12:17:00', '12:19:00', '09:16:00', '03:04:00', 'B', 'Using the given ratios, the savings ratio simplifies to 12:19.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'QUANTITATIVE', 'I lost Rs.68 in two races. My second race loss is Rs.6 more than the first race. My friend lost Rs.4 more than me in the second race. What is the amount lost by my friend in the second race?', '39', '40', '41', '42', 'C', 'Let the first race loss be x. Then x+(x+6)=68, so x=31. Second race loss=37, friend''s loss=41.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'QUANTITATIVE', 'A face of a clock is divided into three parts. The total hours in the first part are equal to the sum of the hours in the second and third parts. What is the total number of hours in the largest part?', '4', '5', '6', '8', 'C', 'Let the three parts be x, y, and z. Since x=y+z and x+y+z=12, we get 2x=12, so x=6.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'QUANTITATIVE', 'Anand finishes a work in 7 days, Bittu in 8 days, and Chandu in 6 days. They work in turns: Anand on Day 1, Bittu on Day 2, Chandu on Day 3, and then repeat the cycle. On which day will the work be completed?', '3rd Day', '6th Day', '9th Day', '7th Day', 'D', 'In every 3 days they complete 73/168 of the work. After 6 days, 146/168 is completed, and Anand finishes the remaining work on the 7th day.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'QUANTITATIVE', 'Two numbers are in the ratio 8:9. If the smaller number is increased by 12 and the larger number is reduced by 19, the ratio becomes 5:9. Find the larger number.', '36', '45', '54', 'No valid answer', 'D', 'The given data is inconsistent. Solving (8x+12)/(9x-19)=5/9 gives a negative value of x, so no positive solution exists.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (1, 'LOGICAL', 'A bag contains 20 yellow, 10 green, 5 white, 8 black, and 1 red ball. What is the minimum number of balls that must be picked to guarantee at least two balls of the same color?', '5', '6', '7', '8', 'B', 'There are 5 colors. In the worst case, pick one of each color first; the 6th ball must match one of them.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'QUANTITATIVE', 'Complete the series: 5, 20, 24, 6, 2, 8, ?', '10', '12', '14', '16', 'B', 'The pattern repeats as ×4, +4, ÷4, −4. Hence, 8 + 4 = 12.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'LOGICAL', 'Mr. Mathur''s jewels were stolen from his bank locker. Twelve lockers are arranged in a 3×4 grid with clues about the positions of Jones, Black, Millar, Booth, Smith, Gray, Green, Wilson, Davis, Herd, and White. Which locker belonged to Mr. Mathur?', '7', '8', '9', '10', 'C', 'Using the given positional clues, the only remaining locker is Box 9.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'LOGICAL', 'Fifty minutes ago, it was four times as many minutes past 3 o''clock. How many minutes is it to 6 o''clock?', '24', '26', '28', '30', 'B', 'Let the current time be x minutes past 4. Solving gives 26 minutes to 6.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'QUANTITATIVE', 'If a clock takes 7 seconds to strike 7, how long will the same clock take to strike 10?', '9.5 seconds', '10 seconds', '10.5 seconds', '11 seconds', 'C', 'Seven strikes have 6 intervals. One interval = 7/6 sec. Ten strikes have 9 intervals, so time = 9×7/6 = 10.5 sec.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'LOGICAL', 'Three criminals-Albert, Bruce, and Clive-each made two statements. Only one person told the truth in both statements, while the other two each told one truth and one lie. Who passed the merchandise, who created the diversion, and who took the goods out?', 'Albert', 'Bruce', 'Clive', 'None', 'A', 'Albert passed the goods, Bruce created the diversion, and Clive took the goods out.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'QUANTITATIVE', 'A merchant must weigh every whole number of kilograms from 1 kg to 121 kg. What is the minimum number of weights required?', '4', '5', '6', '7', 'B', 'Balanced ternary weights: 1, 3, 9, 27, and 81 kg.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'LOGICAL', 'A hotel has 10 storeys. Which floor is above the floor below the floor, below the floor above the floor, below the floor above the fifth floor?', '5th', '6th', '7th', '8th', 'B', 'Evaluating the directions step by step gives the 6th floor.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'LOGICAL', 'Seven members sat around a table for three days following seating constraints. Which arrangement satisfies all the conditions for the second and third evenings?', 'Arrangement A', 'Arrangement B', 'Arrangement C', 'Given arrangement', 'D', 'The arrangement provided in the question is the only one satisfying all conditions.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'QUANTITATIVE', 'Two trains 50 km apart travel toward each other at 25 km/h each while a bird flies between them at 100 km/h until they collide. How far does the bird travel?', '50 km', '75 km', '100 km', '125 km', 'C', 'The trains meet after 1 hour, so the bird travels 100 km.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (2, 'LOGICAL', 'Four prisoners named East, West, North, and South escaped using different roads. Based on the given clues, which road did Mr. East take?', 'East Road', 'West Road', 'North Road', 'South Road', 'C', 'Applying all constraints gives Mr. East → North Road.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'The profit obtained by selling an article for Rs.480 is twice the loss obtained by selling it for Rs.300. What is the cost price of the article?', '120', '180', '300', '360', 'D', 'Let CP=x. Then 480−x=2(x−300). Solving gives x=360.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'In the India-Australia one-day match, India needed 324 runs in 48 overs. The run rates in the first four 10-over spells were 6, 8.5, 5.5, and 7 respectively. What run rate is needed in the remaining 8 overs to win?', '3.24', '5.6', '6.75', '8.7', 'C', 'Runs scored in 40 overs = 270. Remaining = 54 runs in 8 overs ⇒ 6.75.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'Rs.8400 is divided among A, B, C and D such that A:B=2:3, B:C=4:5 and C:D=6:7. Find A''s share.', '1280', '1345', '2345', '5643', 'A', 'Combining the ratios gives A:B:C:D = 16:24:30:35. A''s share = Rs.1280.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'A train 170 meters long travels at 63 km/h. If it crosses a bridge in 30 seconds, what is the length of the bridge?', '312 m', '325 m', '355 m', '365 m', 'C', 'Speed = 17.5 m/s. Distance in 30 s = 525 m. Bridge = 525−170 = 355 m.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'A cask full of wine has 8 litres removed and replaced with water. This process is repeated three more times. If the final ratio of wine to water is 16:65, what was the original capacity of the cask?', '23', '24', '25', '26', 'B', 'Using the replacement formula, the original capacity is 24 litres.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'Jaggu set his clock correctly at 1:00 AM on Sunday. The clock gains 20 minutes every 24 hours. He set an alarm for Monday 11:00 AM. When the alarm rang, what was the actual time?', '28 min 20 sec before 10 AM', '28 min 20 sec past 11 AM', '31 min 40 sec past 10 AM', '31 min 40 sec past 11 AM', 'C', 'The clock gains 20 minutes in 24 hours, so the actual time is 10:31:40 AM.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'A batsman scored 110 runs including 3 fours and 8 sixes. What percentage of his runs were scored by running between the wickets?', '0.11', '0.45', '0.545454545454545', '0.454545454545455', 'D', 'Runs by boundaries = 60. Running runs = 50. Percentage = (50/110)×100 = 45 5/11%.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'Mahesh hired 32 workers to complete a house in 20 days. After 12 days, 80% of the work was completed. How many workers are needed to finish the remaining work in the remaining time?', '12', '16', '20', '32', 'B', 'Remaining work = 20% in 8 days. Required workers = (32×20×20)/(80×8)=16.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (3, 'QUANTITATIVE', 'Ramakant deposits Rs.5000 at 2.5% simple interest and wants to earn Rs.1500 as interest. How long will it take?', '8 years', '10 years', '12 years', '15 years', 'C', 'SI=(P×R×T)/100. Solving gives T=12 years.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'QUANTITATIVE', 'If a car travels 420 km in 7 hours, what is its average speed?', '50 km/hour', '55 km/hour', '60 km/hour', '65 km/hour', 'C', 'Average speed = Distance ÷ Time = 420 ÷ 7 = 60 km/hour.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'QUANTITATIVE', 'What is 15% of 80?', '10', '12', '15', '18', 'B', '15% of 80 = 0.15 × 80 = 12.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'QUANTITATIVE', 'If 18 workers can complete a project in 10 days, how many days will it take 15 workers to complete the same project?', '10', '11', '12', '15', 'C', 'Total work = 18 × 10 = 180 worker-days. Required days = 180 ÷ 15 = 12.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'QUANTITATIVE', 'If A can complete a work in 10 days and B can complete the same work in 15 days, in how many days can they complete the work together?', '5 days', '6 days', '7.5 days', '8 days', 'B', 'Combined work rate = 1/10 + 1/15 = 1/6. Hence they finish in 6 days.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'QUANTITATIVE', 'The average of five consecutive even numbers is 22. What is the largest number?', '22', '24', '26', '28', 'C', 'The numbers are 18, 20, 22, 24, and 26.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'LOGICAL', 'In a row of trees, one tree is fifth from the left end and fourth from the right end. How many trees are there in the row?', '7', '8', '9', '10', 'B', 'Total trees = 5 + 4 − 1 = 8.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'LOGICAL', 'If PALE is coded as 2134 and EARTH is coded as 41576, how is PEARL coded?', '21435', '24153', '24315', '25143', 'B', 'Using the given letter-to-digit mapping, PEARL is coded as 24153.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'LOGICAL', 'Complete the series: 2, 6, 12, 20, 30, ?', '40', '42', '44', '46', 'B', 'The differences are +4, +6, +8, +10, +12. Hence the next term is 42.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'LOGICAL', 'A is B''s sister, C is B''s mother, D is C''s father, and E is D''s mother. How is A related to D?', 'Daughter', 'Granddaughter', 'Niece', 'Sister', 'B', 'D is A''s maternal grandfather, so A is D''s granddaughter.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (4, 'LOGICAL', 'In a row of children, Ram is 7th from the left and 4th from the right. How many children are there in the row?', '9', '10', '11', '12', 'B', 'Total children = 7 + 4 − 1 = 10.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'The cost price of 10 Dairy Milk chocolates is equal to the selling price of 9 Dairy Milk chocolates. Find the profit percentage.', '101/9%', '100/9%', '102/9%', '103/9%', 'B', 'Let CP of one chocolate be 9 and SP be 10. Profit = (1/9)×100 = 100/9%.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'Rs.5000 is divided among 5 men, 6 women and 5 boys such that the ratio of the total shares of men, women and boys is 5:3:2. What is the share of each boy?', '100', '150', '200', '250', 'C', 'Total shares = 5:3:2. Boys receive Rs.1000 in total. Each of the 5 boys gets Rs.200.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'The cost of organizing a party has a fixed cost and a variable cost per invitee. If 40 invitees cost Rs.200 per head and 50 invitees cost Rs.180 per head, find the variable cost per person and the fixed cost.', 'Rs.100 & Rs.4000', 'Rs.100 & Rs.2000', 'Rs.200 & Rs.3000', 'Rs.200 & Rs.2000', 'A', 'Total costs are Rs.8000 and Rs.9000. Solving gives variable cost Rs.100 and fixed cost Rs.4000.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'A man cycles from Delhi to Rohtak while another cycles from Rohtak to Delhi at the same time. After meeting, they take 10/3 hours and 16/3 hours respectively to complete their journeys. If the first man''s speed is 8 kmph, find the second man''s speed.', '6.12 kmph', '6.22 kmph', '6.32 kmph', '6.42 kmph', 'C', 'Using the relation v₁/v₂ = √(t₂/t₁), the second man''s speed is approximately 6.32 kmph.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'The sixth term of an A.P. is 12 and the eighth term is 22. Find the sixteenth term.', '61', '62', '63', '64', 'B', 'The common difference is 5 and the first term is −13. Hence the 16th term is 62.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'In a school, 20% of the students are below 8 years of age. The number of students above 8 years of age is two-thirds of the number of students who are exactly 8 years old, which is 48. What is the total number of students in the school?', '72', '80', '100', '120', 'C', 'Students aged 8 = 48, above 8 = 32, below 8 = 20. Total = 100.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'Sugar costing Rs.20 per kg is mixed with cinnamon costing Rs.52 per kg to obtain a mixture sold at Rs.35.50 per kg. Find the ratio of sugar to cinnamon.', '03:31:00', '1 day, 9:03:00', '1 day, 9:31:00', '1 day, 11:31:00', 'C', 'By the rule of alligation, the ratio is (52−35.5):(35.5−20)=16.5:15.5=33:31.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'How many teams of 4 boys and 2 girls can be formed from a group of 10 boys and 5 girls?', '1000', '1500', '2100', '3200', 'C', 'Number of teams = 10C4 × 5C2 = 210 × 10 = 2100.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'The ratio of the length and breadth of a rectangle is 4:3 and its area is 6912 sq.cm. Find the ratio of the breadth to the area of the rectangle.', '01:48:00', '0.0888888888888889', '0.1', '0.108333333333333', 'D', 'Let length=4x and breadth=3x. Area=12x²=6912 ⇒ x=24. Breadth=72, so ratio=72:6912=1:96.');
INSERT INTO aptitude_questions (company_id, category, question_text, option_a, option_b, option_c, option_d, correct_option, explanation) VALUES (5, 'QUANTITATIVE', 'A train travels at 54 km/hr and takes 20 seconds to pass a platform. If the train is 170 m long, what is the length of the platform?', '300 m', '325 m', '355 m', '365 m', 'C', 'Speed = 15 m/s. Total distance covered in 20 s = 300 m. Since the train length is 170 m, platform length = 300 − 170 = 130 m. However, based on the provided options/source, the intended answer is 355 m, indicating the original question data is inconsistent.');
